private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    while (bb.hasRemaining()) {
        byte b = bb.get(i++);
        if ((b & 0x80) == 0) {
            // Single-byte character
            sb.append((char) b);
        } else if ((b & 0xE0) == 0xC0) {
            // Two-byte character
            if (bb.hasRemaining()) {
                char ch = (char) (((b & 0x1F) << 6) + (bb.get(i++) & 0x3F));
                sb.append(ch);
            } else {
                break;
            }
        } else if ((b & 0xF0) == 0xE0) {
            // Three-byte character
            if (bb.remaining() >= 2) {
                char ch = (char) (((b & 0x0F) << 12) + ((bb.get(i++) & 0x3F) << 6) + (bb.get(i++) & 0x3F));
                sb.append(ch);
            } else {
                break;
            }
        } else if ((b & 0xF8) == 0xF0) {
            // Four-byte character
            if (bb.remaining() >= 3) {
                int codePoint = (((b & 0x07) << 18) + ((bb.get(i++) & 0x3F) << 12) + ((bb.get(i++) & 0x3F) << 6) + (bb.get(i++) & 0x3F));
                sb.append(Character.toChars(codePoint));
            } else {
                break;
            }
        } else {
            // Invalid UTF-8 sequence
            throw new IllegalArgumentException("Invalid UTF-8 sequence");
        }
    }
    return i;
}
